/**
 * Cloudflare Pages worker for the static build (out/_worker.js). Generated by
 * scripts/build-cloudflare.mjs, which fills in the two data blocks below.
 *
 * A static export has no Next.js server, so the URL behaviours that src/proxy.ts and
 * next.config.ts provide on a Node host are done here instead, the same way:
 *
 *   /path/                        301  /path
 *   the 35 Webflow redirects      301  final page, chains resolved
 *   /blog?56e6ea54_page=2         the stored collection-list page, URL unchanged
 *   /blog/~page/…                 404  (internal location, never served under its own URL)
 *   anything else                 the static file; unknown URLs get 404.html with status 404
 *
 * On a *.pages.dev address every page also gets "X-Robots-Tag: noindex": the preview must never
 * be indexed as a copy of signalmash.com. Pointing a real domain at the project lifts that.
 */

/** [from, to] pairs, from src/lib/site/redirects.json */
const REDIRECTS = new Map([["/customer-support-as-service","/support-as-a-service"],["/welcome-to-the-signalmash-developer-hub","/developers"],["/signalmash-for-marketers","/marketing"],["/signalmash-for-product-leaders","/product"],["/signalmash-for-customer-experience","/customer-experience"],["/fraud-prevention-with-signalmash","/fraud-prevention"],["/appointment-reminders-that-keep-your-business-on-schedule","/appointment-reminders"],["/real-time-lead-alerts-with-signalmash","/lead-alerts"],["/mass-texting-made-simple-with-signalmash","/mass-texting"],["/sms-marketing-that-gets-read-and-gets-results","/sms-marketing"],["/grow-revenue-with-signalmash-cpaas","/cross-sell-and-upsell"],["/signalmash-healthcare-solutions","/healthcare-solutions"],["/signalmash-ecommerce-solution","/ecommerce"],["/signalmash-for-hospitality","/hospitality"],["/nonprofit","/non-profit"],["/signalmash-for-nonprofit","/nonprofit"],["/retail-messaging-customer-engagement-solutions","/retail"],["/collections-as-a-service","/payments-as-a-service"],["/signalchat","/coaas"],["/signalmash-ecommerce-solutions","/signalmash-ecommerce-solution"],["/signalmash-for-nonprofits","/signalmash-for-nonprofit"],["/ccaas","/signalcaas"],["/messaging-app","/signalchat"],["/identity-services-number-intelligence","/identity"],["/number","/numbers"],["/nationwide-sms-mms","/toll-free-messaging"],["/text-messaging-api","/text-messaging"],["/sip-trunking-local-termination","/local-termination"],["/sms-marketing-that-gets-read----and-gets-results","/sms-marketing-that-gets-read-and-gets-results"],["/number-intellegence","/number-intelligence"],["/new-toll-free-numbers","/toll-free-numbers"],["/new-local-numbers","/local-numbers"],["/new-10dlc-messaging","/10dlc-messaging"],["/new-toll-free-origination","/toll-free-origination"],["/new-about-us","/about-us"]]);
/** "path?listId_page=N" for every stored collection-list page */
const PAGED = new Set(["/blog?56e6ea54_page=10","/blog?56e6ea54_page=11","/blog?56e6ea54_page=12","/blog?56e6ea54_page=13","/blog?56e6ea54_page=14","/blog?56e6ea54_page=15","/blog?56e6ea54_page=16","/blog?56e6ea54_page=2","/blog?56e6ea54_page=3","/blog?56e6ea54_page=4","/blog?56e6ea54_page=5","/blog?56e6ea54_page=6","/blog?56e6ea54_page=7","/blog?56e6ea54_page=8","/blog?56e6ea54_page=9","/hashtags/ai?de61df57_page=1","/hashtags/ai?de61df57_page=2","/hashtags/business?de61df57_page=10","/hashtags/business?de61df57_page=2","/hashtags/business?de61df57_page=3","/hashtags/business?de61df57_page=4","/hashtags/business?de61df57_page=5","/hashtags/business?de61df57_page=6","/hashtags/business?de61df57_page=7","/hashtags/business?de61df57_page=8","/hashtags/business?de61df57_page=9","/hashtags/communications?de61df57_page=2","/hashtags/communications?de61df57_page=3","/hashtags/communications?de61df57_page=4","/hashtags/communications?de61df57_page=5","/hashtags/communications?de61df57_page=6","/hashtags/communications?de61df57_page=7","/hashtags/communications?de61df57_page=8","/hashtags/contact-centers?de61df57_page=2","/hashtags/contact-centers?de61df57_page=3","/hashtags/customer-experience?de61df57_page=2","/hashtags/customer-experience?de61df57_page=3","/hashtags/customer-experience?de61df57_page=4","/hashtags/cybersecurity?de61df57_page=1","/hashtags/cybersecurity?de61df57_page=2","/hashtags/marketing-growth?de61df57_page=1","/hashtags/marketing-growth?de61df57_page=2","/hashtags/numbers?de61df57_page=1","/hashtags/numbers?de61df57_page=2","/hashtags/rcs?de61df57_page=1","/hashtags/rcs?de61df57_page=2","/hashtags/regulation?de61df57_page=1","/hashtags/regulation?de61df57_page=2","/hashtags/tech-for-good?de61df57_page=1","/hashtags/tech-for-good?de61df57_page=2","/hashtags/technology?de61df57_page=2","/hashtags/technology?de61df57_page=3","/hashtags/technology?de61df57_page=4","/hashtags/technology?de61df57_page=5","/hashtags/technology?de61df57_page=6","/hashtags/telecom-infrastructure?de61df57_page=2","/hashtags/telecom-infrastructure?de61df57_page=3","/hashtags/text-messaging?de61df57_page=2","/hashtags/text-messaging?de61df57_page=3","/hashtags/text-messaging?de61df57_page=4","/hashtags/text-messaging?de61df57_page=5"]);

const PAGED_PARAM = /^([0-9a-f]+)_page$/;

function finalTarget(path) {
  let to = REDIRECTS.get(path);
  for (let hops = 0; REDIRECTS.has(to) && hops < 10; hops++) to = REDIRECTS.get(to);
  return to;
}

function withHeaders(response, url) {
  const res = new Response(response.body, response);
  if (url.hostname.endsWith(".pages.dev")) res.headers.set("X-Robots-Tag", "noindex");
  return res;
}

const worker = {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (path.length > 1 && path.endsWith("/")) {
      url.pathname = path.replace(/\/+$/, "") || "/";
      return Response.redirect(url.toString(), 301);
    }

    const to = finalTarget(path);
    if (to) return Response.redirect(new URL(to + url.search, url).toString(), 301);

    if (path.split("/").includes("~page")) {
      const missing = await env.ASSETS.fetch(new URL("/404.html", url));
      return withHeaders(new Response(missing.body, { status: 404, headers: missing.headers }), url);
    }

    for (const [name, value] of url.searchParams) {
      const listId = name.match(PAGED_PARAM)?.[1];
      if (!listId || !PAGED.has(`${path}?${name}=${value}`)) continue;
      const stored = new URL(`${path === "/" ? "" : path}/~page/${listId}/${value}`, url);
      return withHeaders(await env.ASSETS.fetch(stored), url);
    }

    return withHeaders(await env.ASSETS.fetch(request), url);
  },
};

export default worker;
